<?php $page_title='Request Details'; require_once __DIR__.'/includes/header.php';$id=(int)($_GET['id']??0);$r=one('SELECT * FROM trial_requests WHERE id=?',[$id]);if(!$r){flash('danger','Request not found.');redirect('trial-requests.php');}?><div class="row"><div class="col-md-8"><div class="card"><div class="card-body"><h3><?=e($r['name'])?> <?=status_badge($r['status'])?></h3><div class="row"><?php foreach(['email','whatsapp','country','dial_code','device','plan','ip_address','created_at'] as $f): ?><div class="col-md-6"><small class="text-muted"><?=e(ucwords(str_replace('_',' ',$f)))?></small><p><?=e($r[$f])?></p></div><?php endforeach; ?></div><h5>Message</h5><pre class="pre-wrap"><?=e($r['message'])?></pre></div></div></div><div class="col-md-4"><div class="card"><div class="card-body"><h5>Actions</h5><a class="btn btn-secondary w-100 mb-3" href="request-edit.php?id=<?=$id?>">Edit</a><form method="post" action="whatsapp-send.php"><?=csrf_field()?><input type="hidden" name="request_id" value="<?=$id?>"><button class="btn btn-primary w-100">Send WhatsApp Notification</button></form></div></div></div></div><?php require_once __DIR__.'/includes/footer.php'; ?>
